     * 0.02, from `packages/react-ui/src/layout/SplitPane.tsx`.
     */
    const val splitPaneStep: Float = 0.02f

    /**
     * How far Page Up and Page Down move a SplitPane's divider, as a share of the split, the web's
     * `PAGE_STEP`. 0.1, from `packages/react-ui/src/layout/SplitPane.tsx`.
     */
    const val splitPanePageStep: Float = 0.1f

    /**
     * The step of ImageEditor's zoom, as a fraction of the zoom that covers the frame, the web's
     * `ZOOM_SLIDER_STEP`. 5%, from `packages/react-ui/src/controls/ImageEditor.tsx`.
     */
    const val imageEditorZoomStep: Float = 0.05f

    /**
     * How far an arrow key pans ImageEditor's picture, the web's `PAN_STEP`. 8px, a dp each, from
     * `packages/react-ui/src/controls/ImageEditor.tsx`.
     */
    val imageEditorPanStep: Dp get() = 8.dp

    /**
     * How far an arrow key with Shift pans ImageEditor's picture, the web's `PAN_STEP_LARGE`. 32px,
     * a dp each, from `packages/react-ui/src/controls/ImageEditor.tsx`.
     */
    val imageEditorPanStepLarge: Dp get() = 32.dp

    /**
     * The opacity of ImageEditor's rule-of-thirds lines, drawn while the picture is panned. 0.6,
     * from `controls/image-editor.module.css`.
     */
    const val imageEditorGridOpacity: Float = 0.6f
}
